example:
capability Clock {
    fn now() -> Effect[Int]
    fn zone() -> Effect[String]
}

provides Clock = Fixed {         // ✗ no `zone`
    fn now() -> Effect[Int] { Effect.pure(0) }
}

provides Clock = Fixed {         // ✓ every operation is provided
    fn now() -> Effect[Int] { Effect.pure(0) }
    fn zone() -> Effect[String] { Effect.pure("UTC") }
}
